import ast
import json
import math
import random
from fractions import Fraction
from pathlib import Path
root=Path('/workspace')
r=json.load(open('/tmp/r001_contract.json'))
p=json.load(open(root/'proposal.json'))
def validate(x,s,path='"'$'"'):
 t=s.get('type')
 match={'object':lambda z:isinstance(z,dict),'array':lambda z:isinstance(z,list),'string':lambda z:isinstance(z,str)}
 if t: assert match[t](x),(path,'type',t)
 if 'const' in s: assert type(x) is type(s['const']) and x==s['const'],(path,'const')
 if 'enum' in s: assert x in s['enum'],(path,'enum')
 if isinstance(x,str) and 'minLength' in s: assert len(x)>=s['minLength'],path
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x): validate(v,s.get('items',{}),path+'['+str(i)+']')
 if isinstance(x,dict):
  assert set(s.get('required',[]))<=set(x),(path,'missing required')
  if s.get('additionalProperties') is False: assert set(x)<=set(s.get('properties',{})),(path,'unexpected properties')
  for k,v in x.items():
   if k in s.get('properties',{}): validate(v,s['properties'][k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
classes=[]
for v in p['variants']:
 assert v['file']==Path(v['file']).name and v['file'].endswith('.py')
 assert v['role'] in ['candidate','control']
 s=(root/v['file']).read_text(); tree=ast.parse(s);compile(s,v['file'],'exec')
 cfg=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert v['config']==cfg
 assert not set(cfg)&{'epochs','batch_size','train_seed','dense_learning_rate','sparse_learning_rate','history_limit','history_policy'}
 allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in allowed for a in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allowed
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','__import__'}
 classes.append(ast.dump(next(n for n in tree.body if isinstance(n,ast.ClassDef))))
assert len(set(classes))==1
assert {(v['config']['background_scope'],v['config']['exclude_slot']) for v in p['variants']}=={('global',False),('global',True),('band',False),('band',True)}
assert set(r['context']['latest_knowledge_usage']['retrieved_ids']) <= {k['knowledge_id'] for k in p['knowledge_assessments']}
print('Proposal matches study schema, authorized evidence IDs, complete factorial, module configs and import boundary.')

# Independent exact-rational specification checks, not tensor execution.
def gate(counts,positives,scope,exclude):
 ans=[]
 for slot,n in enumerate(counts):
  f=Fraction(positives[slot],max(n,1))
  group=range(8) if scope=='global' else range(slot//4*4,slot//4*4+4)
  nprior=sum(counts[i] for i in group);kprior=sum(positives[i] for i in group)
  if exclude: nprior-=n;kprior-=positives[slot]
  background=Fraction(kprior,nprior) if nprior else f
  w=Fraction(n,n+4)
  ans.append(w*f+(1-w)*background)
 return ans
rand=random.Random(55)
for _ in range(500):
 counts=[rand.randrange(13) for _ in range(8)]
 positives=[rand.randrange(n+1) for n in counts]
 for scope in ['global','band']:
  for exclude in [False,True]:
   assert all(0<=g<=1 for g in gate(counts,positives,scope,exclude))
 # Band/global scope equality where all events occupy only one band.
 for occupied_band in [0,1]:
  c=[n if i//4==occupied_band else 0 for i,n in enumerate(counts)]
  k=[n if i//4==occupied_band else 0 for i,n in enumerate(positives)]
  for exclude in [False,True]:
   g1=gate(c,k,'global',exclude);g2=gate(c,k,'band',exclude)
   assert all(g1[i]==g2[i] for i in range(8) if c[i]>0)
 # Decompose the inclusive global gate into local/complementary rates.
 total=sum(counts)
 if total:
  gates=gate(counts,positives,'global',False)
  for i,n in enumerate(counts):
   if n and total>n:
    f=Fraction(positives[i],n)
    peer=Fraction(sum(positives)-positives[i],total-n)
    offslot=Fraction(4*(total-n),total*(n+4))
    assert gates[i]==(1-offslot)*f+offslot*peer
for scope in ['global','band']:
 for exclude in [False,True]:
  assert gate([0]*8,[0]*8,scope,exclude)==[0]*8
for i in range(8):
 c=[0]*8;k=[0]*8;c[i]=3;k[i]=1
 for scope in ['global','band']:
  assert gate(c,k,scope,True)[i]==Fraction(1,3)
print('500 rational count/feedback cases: gate bounds, occupied-slot single-band equality, empty/no-peer fallback and inclusive effective-dose identity passed. Tensor and BF16 checks remain unrun.')
print('Expected outputs present:', ', '.join(['proposal.json']+[v['file'] for v in p['variants']]))
